{
  "avaliacoes": [
    {
      "id": "Eb6dae81b64043f15",
      "pertinente": true,
      "tipo": "resultado_experimental",
      "achados": [
        {
          "proposicao": "Em auditoria focada em barreiras de incêndio e explosão, foram observados numerosos reparos temporários e não certificados em linhas críticas, inclusive em redes de combate a incêndio, sem a documentação requerida, indicando comprometimento da integridade e da rastreabilidade de intervenções em sistemas relevantes para a resposta a emergências.",
          "trechos": [
            "Eb6dae81b64043f15:0:691",
            "Eb6dae81b64043f15:691:1386"
          ],
          "condicoes": [
            "Auditoria da SSM em 2020 em cinco instalações operadas pela Petrobras",
            "Avaliação das barreiras de contenção primária, sistemas de detecção e sistema de despressurização"
          ],
          "limites": [
            "O trecho não informa quais linhas de combate a incêndio estavam afetadas nem a extensão da indisponibilidade",
            "Não há quantificação do efeito desses reparos sobre pressão, vazão ou desempenho do sistema"
          ]
        },
        {
          "proposicao": "A auditoria tratou como ponto crítico o estabelecimento de prazo para executar recomendação técnica de inspeção classificada como crítica, entendendo que, se o elemento permanecer em operação, caracteriza-se risco grave e iminente; isso relaciona o gerenciamento de pendências críticas à aceitabilidade operacional de equipamentos e linhas relevantes para cenários de incêndio e explosão.",
          "trechos": [
            "Eb6dae81b64043f15:1386:2086",
            "Eb6dae81b64043f15:2086:2352"
          ],
          "condicoes": [
            "Quando a recomendação de inspeção é classificada como crítica",
            "Quando o elemento não é retirado de operação"
          ],
          "limites": [
            "O trecho não detalha medidas compensatórias aceitáveis caso haja manutenção da operação",
            "Não identifica qual equipamento ou linha motivou a recomendação crítica"
          ]
        },
        {
          "proposicao": "Foi identificado procedimento inadequado para garantia da qualidade de reparos temporários em linhas críticas, incluindo linhas pressurizadas e de fluido perigoso, o que evidencia falha de controle de manutenção com potencial repercussão na confiabilidade operacional de barreiras de resposta a incêndio.",
          "trechos": [
            "Eb6dae81b64043f15:2086:2352"
          ],
          "condicoes": [
            "No contexto dos principais desvios identificados na auditoria de 2020"
          ],
          "limites": [
            "O trecho não explicita o procedimento inadequado nem o critério técnico de aceitação",
            "A relação com desempenho em incêndio é contextual, não demonstrada por teste no excerto"
          ]
        }
      ]
    },
    {
      "id": "E30b98a3ffeda561f",
      "pertinente": true,
      "tipo": "resultado_experimental",
      "achados": [
        {
          "proposicao": "Em uma instalação auditada, havia vazamentos de gás e as linhas de gas lift e de combate a incêndio encontravam-se em avançado grau de corrosão, sendo concluído que os planos e procedimentos de inspeção, teste e manutenção não garantiam a integridade mecânica de sistemas, estruturas, equipamentos e sistemas críticos de segurança operacional.",
          "trechos": [
            "E30b98a3ffeda561f:0:699",
            "E30b98a3ffeda561f:699:1399"
          ],
          "condicoes": [
            "Achado de fiscalização referente à PCM-08",
            "Presença simultânea de vazamentos e corrosão avançada"
          ],
          "limites": [
            "O trecho não quantifica a perda de espessura, vazão disponível ou redução de capacidade do sistema de combate a incêndio",
            "Trata-se de evidência de caso concreto"
          ]
        },
        {
          "proposicao": "Durante teste de partida do motor da bomba de combate a incêndio em outra instalação, a bomba não funcionou e foi identificado alto grau de corrosão nas linhas de combate a incêndio, mostrando associação entre teste funcional malsucedido e degradação da rede do sistema.",
          "trechos": [
            "E30b98a3ffeda561f:699:1399"
          ],
          "condicoes": [
            "Achado de fiscalização referente à PGA-03",
            "Durante teste realizado de partida do motor da bomba"
          ],
          "limites": [
            "O trecho não informa a causa imediata da falha de partida",
            "Não há detalhamento sobre redundância, bomba reserva ou medidas compensatórias adotadas"
          ]
        },
        {
          "proposicao": "A fonte associa a indisponibilidade ou inadequação de sistemas e equipamentos de emergência à ausência de certificação operacional do operador quanto à disponibilidade dos recursos de resposta e à insuficiência de planos e procedimentos de inspeção, teste e manutenção orientados à integridade mecânica.",
          "trechos": [
            "E30b98a3ffeda561f:0:699",
            "E30b98a3ffeda561f:699:1399"
          ],
          "condicoes": [
            "No contexto dos achados reportados pela ANP em 2013"
          ],
          "limites": [
            "O trecho não estabelece um método específico de verificação da disponibilidade",
            "Não define periodicidades ou critérios quantitativos de aceitação"
          ]
        }
      ]
    },
    {
      "id": "E2cd027f2222ce821",
      "pertinente": false,
      "tipo": "indeterminado",
      "achados": []
    },
    {
      "id": "Ee8bb0b543d49f847",
      "pertinente": true,
      "tipo": "resultado_experimental",
      "achados": [
        {
          "proposicao": "Em auditoria de instalação de produção, foi observado que o plano de manutenção, teste e inspeção de equipamento crítico não estava sendo cumprido conforme a recomendação do fabricante, o que a fonte enquadra como gerenciamento inadequado da integridade de sistemas e equipamentos críticos.",
          "trechos": [
            "Ee8bb0b543d49f847:695:1385"
          ],
          "condicoes": [
            "No contexto das auditorias realizadas em 2015",
            "Aplicado a equipamento crítico em instalação de produção"
          ],
          "limites": [
            "O trecho não identifica o equipamento crítico específico",
            "Não informa qual recomendação do fabricante deixou de ser cumprida"
          ]
        },
        {
          "proposicao": "Em instalações de perfuração auditadas, foram identificados casos de sistema de combate a incêndio inoperante, evidenciando indisponibilidade de barreira ativa de emergência no momento da fiscalização.",
          "trechos": [
            "Ee8bb0b543d49f847:695:1385"
          ],
          "condicoes": [
            "Achado em unidades marítimas de perfuração"
          ],
          "limites": [
            "O trecho não descreve qual subsistema de combate a incêndio estava inoperante",
            "Não há informação sobre duração da inoperância ou contingências adotadas"
          ]
        },
        {
          "proposicao": "A falta de peças ou equipamentos sobressalentes foi apontada em sistemas e equipamentos críticos, incluindo ausência de sobressalente para manter a disponibilidade de canhões de incêndio em instalação de produção, relacionando gestão de sobressalentes à disponibilidade operacional do sistema de combate a incêndio.",
          "trechos": [
            "Ee8bb0b543d49f847:1385:2079"
          ],
          "condicoes": [
            "No contexto de auditorias em instalações marítimas de produção e perfuração",
            "Quando a manutenção da disponibilidade depende de sobressalentes"
          ],
          "limites": [
            "O trecho não quantifica o número de canhões afetados",
            "Não informa estoque mínimo, prazo de reposição ou impacto hidráulico no sistema"
          ]
        }
      ]
    },
    {
      "id": "E091d957481edf3a5",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "A fonte explica que, nos estágios iniciais de um incêndio, enquanto se busca parar a unidade, isolar fluxos inflamáveis e acionar os sistemas ativos de combate a incêndio, suportes de tubulações, equipamentos e elementos estruturais sem proteção podem perder resistência e colapsar, favorecendo falhas de juntas, rompimento de linhas ou equipamentos e vazamento de hidrocarbonetos.",
          "trechos": [
            "E091d957481edf3a5:0:699"
          ],
          "condicoes": [
            "Durante os estágios iniciais de um incêndio",
            "Na ausência de proteção dos suportes, equipamentos e elementos estruturais expostos"
          ],
          "limites": [
            "O trecho trata de proteção passiva contra incêndio e de consequências de perda estrutural, não de critérios de partida de bombas ou testes de sistemas ativos",
            "Não há parametrização temporal além da descrição qualitativa do estágio inicial"
          ]
        },
        {
          "proposicao": "As aplicações típicas de proteção passiva contra incêndio em regiões críticas são apresentadas como dependentes de avaliação específica para cada instalação, considerando estudos de propagação de incêndio e explosão e a estratégia de resposta a emergência adotada.",
          "trechos": [
            "E091d957481edf3a5:699:1399"
          ],
          "condicoes": [
            "No uso das diretrizes e indicações da ISO 13702:2015 citada pela própria fonte",
            "Para regiões críticas de instalações marítimas de produção"
          ],
          "limites": [
            "A fonte remete à necessidade de avaliação específica, sem fornecer no excerto critérios de seleção ou cobertura",
            "Não converte a indicação típica em requisito universal para toda instalação"
          ]
        },
        {
          "proposicao": "A ausência, degradação ou instalação fora de especificação de proteção passiva contra incêndio é apresentada como fator que facilita o escalonamento do cenário acidental, reduzindo o tempo disponível para evacuação segura e para controle da emergência.",
          "trechos": [
            "E091d957481edf3a5:1399:2092"
          ],
          "condicoes": [
            "Quando a PPCI está ausente, degradada ou fora de especificação"
          ],
          "limites": [
            "O trecho aborda consequência operacional qualitativa, sem medir redução de tempo ou taxa de escalonamento",
            "A relação com disponibilidade de sistemas ativos é indireta"
          ]
        }
      ]
    },
    {
      "id": "Ef66f8165b5ed9ad8",
      "pertinente": true,
      "tipo": "resultado_experimental",
      "achados": [
        {
          "proposicao": "Na verificação de condicionantes do FPSO Carioca, o operador não havia realizado teste de desempenho do sistema fixo de CO2 com acionamento do sistema e verificação da concentração de CO2 nos ambientes, embora esse teste tenha sido tratado pela fonte como exigência normativa de referência para o sistema.",
          "trechos": [
            "Ef66f8165b5ed9ad8:698:1395",
            "Ef66f8165b5ed9ad8:1395:2086"
          ],
          "condicoes": [
            "Durante auditoria pré-operacional remota de 2021",
            "Na verificação das condicionantes ligadas a testes de desempenho de sistemas críticos"
          ],
          "limites": [
            "O trecho trata de caso específico de auditoria pré-operacional",
            "Não apresenta a sequência completa de teste nem todos os critérios de aceitação do sistema"
          ]
        },
        {
          "proposicao": "A aceitação, pela classificadora, de não realizar os testes mediante waiver não foi considerada compatível com o arcabouço regulatório brasileiro pela fonte, que vincula planos e procedimentos de teste da integridade de sistemas críticos ao alinhamento com normas, padrões e boas práticas de engenharia.",
          "trechos": [
            "Ef66f8165b5ed9ad8:1395:2086"
          ],
          "condicoes": [
            "No contexto do sistema de CO2 do FPSO Carioca",
            "Após solicitação do operador e concessão de waiver pela classificadora"
          ],
          "limites": [
            "O trecho não desdobra todos os requisitos brasileiros aplicáveis além da referência ao item 13.2.1 da Resolução ANP nº 43/2007 citada pela própria fonte",
            "Não transforma automaticamente exigência de norma estrangeira em requisito brasileiro sem essa mediação regulatória expressa no texto"
          ]
        },
        {
          "proposicao": "Após determinação da ANP para realização do teste, foram constatados desvios relevantes no sistema de CO2, incluindo falha na aplicação do critério de projeto para os compartimentos protegidos e não atendimento da concentração requerida após dois minutos, demonstrando que a execução do teste revelou incompatibilidades de projeto e desempenho que não haviam sido comprovadas antes.",
          "trechos": [
            "Ef66f8165b5ed9ad8:1395:2086",
            "Ef66f8165b5ed9ad8:2086:2469"
          ],
          "condicoes": [
            "Após a realização do teste determinado pela ANP",
            "No sistema de CO2 do FPSO Carioca"
          ],
          "limites": [
            "O trecho não informa o valor da concentração requerida nem os parâmetros completos do ensaio",
            "Os desvios descritos referem-se aos compartimentos citados no caso concreto"
          ]
        }
      ]
    }
